parameters.jsCode:
// Format email: turn the AI text into a simple HTML email and add your signature from Settings.
const s = $('Settings').first().json;
const row = $('Active vendors only').item.json;
const out = $json.output || {};
const esc = (t) => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const body = String(out.body || '').trim();
const html = esc(body).split(/\n{2,}/).map((p) => '<p>' + p.replace(/\n/g, '<br>') + '</p>').join('') + (s.SIGNATURE_HTML || '');
// Flag anything odd in the subject so you notice it in Drafts.
const flag = !body ? '[CHECK: empty update] ' : (/https?:\/\//i.test(body) ? '[CHECK: contains a link] ' : '');
return { json: {
  to: String(row.vendor_email).trim(),
  subject: flag + (String(out.subject || '').trim() || 'Your weekly update: ' + row.property_address),
  html,
} };
